#!/usr/bin/env python3
"""Deterministic five-source ingest -> wiki -> slide deck. Uses curated, attributed source notes.
No API keys or online runtime dependencies; LLM summaries were reviewed during preparation.
"""
import json, html, pathlib, datetime
from collections import defaultdict
ROOT = pathlib.Path(__file__).resolve().parent
sources = sorted([json.loads(p.read_text(encoding='utf8')) for p in (ROOT/'raw').glob('S*.json')],key=lambda a:a['id'])
plan = json.loads((ROOT/'slide_plan.json').read_text(encoding='utf8'))
assert len(sources)>=5 and len({s['url'] for s in sources})>=5
source_by_id={s['id']:s for s in sources}
# LLM-written Markdown is now the knowledge source. Building the HTML must NEVER overwrite it.
# Five original, attributed source cards live in raw/S*.md and their source metadata in raw/S*.json.
def read_concept(s):
    path=ROOT/'wiki'/f"{s['concept_id']}.md"
    if not path.exists(): raise FileNotFoundError(path)
    content=path.read_text(encoding='utf8')
    parts=content.split('\n')
    if parts[0] != '# '+s['topic']:
        raise ValueError(f"Title mismatch in {path.name}: {parts[0]!r}")
    if f"[{s['id']}]" not in content or s['url'] not in content:
        raise ValueError(f"Missing source citation in {path.name}")
    def section(name):
        a=content.split(f'## {name}\n',1)
        if len(a)!=2: raise ValueError(f'Missing {name}: {path}')
        return a[1].split('\n## ',1)[0].strip()
    intro=content.split('\n\n',1)[1].split('\n## ',1)[0].strip()
    facts=[line[2:] for line in section('重要概念').splitlines() if line.startswith('- ')]
    related=[x[4:-2] for x in section('相關頁面').splitlines() if x.startswith('- [[') and x.endswith(']]')]
    return {'id':s['concept_id'],'title':s['topic'],'description':intro,'facts':facts,'safety_check':section('檢查點'),'sources':[s['id']],'related':related}
concepts=[read_concept(s) for s in sources]
concept_by_id={c['id']:c for c in concepts}
for c in concepts:
    for link in c['related']:
        if link not in concept_by_id: raise ValueError(f'Broken Wiki link: {c["id"]}->{link}')


def esc(s):return html.escape(str(s),quote=True)
def src_links(ids,cls='sources'):
    if not ids:return ''
    return '<div class="'+cls+'"><span>WIKI SOURCES</span> '+' '.join(f'<a href="wiki.html#{source_by_id[s]["concept_id"]}" title="{esc(source_by_id[s]["title"])}">[{s}]</a>' for s in ids)+'</div>'
def tag(tag,text):return f'<{tag}>{esc(text)}</{tag}>'
def callout(text):return f'<div class="note"><span class="note-label">KEY IDEA</span><p>{esc(text)}</p></div>'

def slide_body(s):
    k=s['kind']
    if k=='cover':
        return '<div class="cover-visual"><div class="binary-chip">0 <span>→</span> 1</div><div class="cover-path">LOGIC GATES <b>·</b> ADDERS <b>·</b> MEMORY <b>·</b> FSM</div></div><p class="lead">每一個複雜數位系統，都從簡單的 0 與 1 開始。</p><p class="muted">使用 ← / → 鍵翻頁，或點擊下方按鈕。</p>'
    if k=='objectives':
        return '<p class="lead">不需要電子電路基礎，也能在 10 分鐘掌握一條學習主線。</p><div class="objectives">'+''.join(f'<div class="objective"><b>0{i+1}</b><span>{esc(t)}</span></div>' for i,t in enumerate(s['items']))+'</div>'
    if k=='truth':
        return '<p class="lead">邏輯閘（Logic Gate）接收 0 或 1，依規則輸出 0 或 1。</p><div class="two-col"><div><table class="truth-table"><thead><tr><th>A</th><th>B</th><th>AND</th><th>OR</th><th>XOR</th></tr></thead><tbody>'+''.join(f'<tr><td>{a}</td><td>{b}</td><td>{a&b}</td><td>{a|b}</td><td>{a^b}</td></tr>' for a in (0,1) for b in (0,1))+'</tbody></table><p class="muted">NOT 只有一個輸入：NOT 0 = 1；NOT 1 = 0。</p></div><div class="live-panel"><p class="panel-heading">互動試試看</p><div class="bit-row"><button class="bit" type="button" id="logicA" aria-label="切換 A">A = <strong>0</strong></button><button class="bit" type="button" id="logicB" aria-label="切換 B">B = <strong>0</strong></button></div><div class="result-grid"><div>AND <b id="logicAnd">0</b></div><div>OR <b id="logicOr">0</b></div><div>XOR <b id="logicXor">0</b></div></div></div></div>'+callout(concept_by_id['C01']['facts'][0]+' '+concept_by_id['C01']['facts'][1]+' '+concept_by_id['C01']['facts'][3])
    if k=='xor':
        return '<p class="lead">當 A = 1、B = 1，OR 與 XOR 的結果剛好不同。</p><div class="compare-pairs"><div class="pair"><span>OR</span><div class="expression">1 OR 1</div><div class="answer">1</div><p>至少一個是 1，因此輸出 1。</p></div><div class="pair"><span>XOR</span><div class="expression">1 XOR 1</div><div class="answer">0</div><p>兩個輸入相同，因此輸出 0。</p></div></div>'+callout(concept_by_id['C01']['safety_check'])
    if k=='nand':
        return '<p class="lead">NAND 是 AND 之後反相；把 NAND 重複組合，能實作其他基本閘。</p><div class="formula-block"><span>AND</span><b>A ∧ B</b><i>→</i><span>NOT</span><b>¬(A ∧ B)</b><i>= NAND</i></div><div class="formula-block alt"><span>範例</span><b>NAND(A, A) = NOT(A)</b></div>'+callout(concept_by_id['C01']['facts'][4])
    if k=='adder':
        return '<p class="lead">用兩個邏輯運算，就能做最簡單的二進位加法。</p><div class="two-col"><div class="math-card"><span class="mini-label">HALF ADDER</span><div class="mathline">Sum = A XOR B</div><div class="mathline">Carry = A AND B</div><p class="muted">若 A = 1、B = 1，答案是二進位 10：和位 0、進位 1。</p></div><div class="live-panel"><p class="panel-heading">試著切換兩個輸入</p><div class="bit-row"><button class="bit" id="addA" type="button">A = <strong>0</strong></button><button class="bit" id="addB" type="button">B = <strong>0</strong></button></div><div class="result-grid"><div>Sum <b id="addSum">0</b></div><div>Carry <b id="addCarry">0</b></div></div><p id="addExplanation" class="muted">0 + 0 = 00（2 進位）</p></div></div>'+callout(concept_by_id['C02']['safety_check'])
    if k=='dff':
        return '<p class="lead">組合邏輯不儲存以前的結果；D Flip-Flop（DFF）能記住一個位元。</p><div class="dff-demo"><div class="block-dff"><span>D</span><strong>正緣 DFF</strong><span>Q</span></div><div class="clockline"><span>CLK</span><svg viewBox="0 0 520 90" role="img" aria-label="時鐘波形有三個上升緣"><path d="M0 65 H75 V18 H150 V65 H240 V18 H315 V65 H405 V18 H485 V65 H520" fill="none" stroke="currentColor" stroke-width="4"/></svg></div></div><div class="dff-steps"><div><b>① 上升緣之前</b><p>D 可以改變，Q 暫時維持舊值。</p></div><div><b>② 時鐘上升緣</b><p>以正緣觸發 DFF 為例，把 D 的值載入 Q。</p></div><div><b>③ 下一個上升緣前</b><p>Q 維持剛才記住的值。</p></div></div>'+callout(concept_by_id['C03']['safety_check'])
    if k=='comparison':
        return '<div class="compare-pairs"><div class="pair"><span>COMBINATIONAL</span><h3>組合邏輯</h3><p>輸出取決於現在的輸入</p><p class="example">例：AND、OR、加法器</p></div><div class="pair"><span>SEQUENTIAL</span><h3>時序邏輯</h3><p>輸出或下一狀態還依賴記住的狀態</p><p class="example">例：暫存器、同步計數器、FSM</p></div></div>'+callout(concept_by_id['C04']['safety_check'])
    if k=='fsm':
        return '<p class="lead">有限狀態機（FSM）描述「目前在哪個狀態，以及什麼條件會切到下一個狀態」。</p><div class="fsm-stage"><div class="fsm-nodes"><div id="offNode" class="fsm-node active">OFF<small>燈熄滅</small></div><div class="fsm-arrows">按一下按鈕 ⇄</div><div id="onNode" class="fsm-node">ON<small>燈點亮</small></div></div><div class="fsm-controls"><button id="fsmToggle" type="button" class="action-button">按一下按鈕</button><p id="fsmStateText" aria-live="polite">目前狀態：OFF</p></div></div><p class="muted">這是我們自製的「開關燈」簡化示例：每次按下視為一次事件。實體電路還需要處理按鈕去彈跳。</p>'+callout(concept_by_id['C05']['facts'][0]+' '+concept_by_id['C05']['facts'][1])
    if k=='chain':
        return '<p class="lead">不是把五篇文章貼在一起，而是依先備知識重新安排教學順序。</p><div class="chain">'+''.join(f'<a href="wiki.html#{c["id"]}"><small>{c["sources"][0]}</small><b>{esc(c["title"])}</b><span>閱讀 Wiki →</span></a>' for c in concepts)+'</div><p class="muted">每個教學節點都有對應的來源標記（例如 [S02]）；點擊簡報底部的來源可回到 Wiki。</p>'
    if k=='quiz':
        questions=[('Q1. 當 A=1、B=1，A XOR B 是多少？',['0','1'],0,'XOR 只在兩個輸入不同時輸出 1。'),('Q2. 半加器的進位 Carry 使用哪個邏輯？',['OR','AND','NOT'],1,'Carry = A AND B。'),('Q3. FSM 最重要的特徵是什麼？',['只看目前輸入','具有狀態與轉移規則'],1,'FSM 依目前狀態和輸入條件決定下一狀態。')]
        blocks=[]
        for i,(q,opts,correct,why) in enumerate(questions):
            choices=''.join(f'<label class="quiz-choice"><input type="radio" name="q{i}" value="{j}"><span>{esc(opt)}</span></label>' for j,opt in enumerate(opts))
            blocks.append(f'<fieldset class="quiz-q" data-correct="{correct}" data-why="{esc(why)}"><legend>{esc(q)}</legend><div class="choices">{choices}</div><p class="quiz-feedback" aria-live="polite"></p></fieldset>')
        return '<div class="quiz-list">'+''.join(blocks)+'</div><div class="quiz-actions"><button class="action-button" id="quizCheck" type="button">批改答案</button><span id="quizTotal" aria-live="polite"></span></div>'
    if k=='end':
        return '<p class="lead">你已經知道如何由基本邏輯閘，理解更高階的數位系統。</p><div class="end-summary"><b>0 / 1</b><span>→ 邏輯閘 → 加法器 → 記憶元件 → 時序邏輯 → 有限狀態機</span></div><p>所有教學重點都能追溯至以下 Wiki 頁面和來源。</p><div class="end-sources">'+''.join(f'<a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">[{s["id"]}] {esc(s["publisher"])} · {esc(s["title"])}</a>' for s in sources)+'</div><div class="final-actions"><a href="wiki.html">開啟完整 Wiki</a><a href="workflow.html">檢視工作流程與檢查紀錄</a></div>'
    raise ValueError(k)

slides_html=[]
for i,s in enumerate(plan):
    slides_html.append(f'<article class="slide" data-index="{i}" id="slide-{s["id"]}" aria-label="第 {i+1} 張：{esc(s["title"])}" {"" if i==0 else "hidden"}><div class="slide-top"><span>{esc(s["kicker"])}</span><span>LESSON / {i+1:02d}—{len(plan):02d}</span></div><div class="slide-content"><h1>{esc(s["title"])}</h1>{"<p class=\"subtitle\">"+esc(s["subtitle"])+"</p>" if s.get("subtitle") else ""}{slide_body(s)}</div>{src_links(s.get('source_ids',[]))}</article>')

slide_css=r'''*{box-sizing:border-box} :root{--ink:#162536;--muted:#64748b;--accent:#0b706d;--line:#d9e2e8;--paper:#f5f8fa;--white:#fff;--pale:#eaf5f2}html,body{margin:0;min-height:100%;font-family:system-ui,-apple-system,"Noto Sans TC","Microsoft JhengHei",sans-serif;background:#e8edf0;color:var(--ink)}button,a{font:inherit}a{color:var(--accent)}button{cursor:pointer}.topbar{height:64px;background:var(--ink);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(16px,3vw,44px);gap:14px}.topbar a{color:#fff;text-decoration:none}.brand{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:800;letter-spacing:.08em}.brand-mark{background:#f9d57e;border-radius:4px;color:var(--ink);font:900 15px ui-monospace,monospace;padding:7px}.topbar nav{display:flex;gap:20px;font-size:13px}.topbar nav a:hover{text-decoration:underline}.deck-shell{max-width:1260px;margin:28px auto 14px;padding:0 16px}.slide{background:var(--white);border:1px solid #ced8df;box-shadow:0 12px 36px #1e314116;min-height:min(690px,calc(100vh - 155px));border-radius:8px;position:relative;display:flex;flex-direction:column;overflow:hidden}.slide[hidden]{display:none}.slide:before{content:"";position:absolute;left:0;top:0;bottom:0;width:7px;background:var(--accent)}.slide-top{display:flex;justify-content:space-between;padding:28px 52px 0;font:700 12px ui-monospace,monospace;letter-spacing:.07em;color:var(--muted)}.slide-content{padding:30px 70px 28px;flex:1}h1{font-size:clamp(28px,4.1vw,52px);line-height:1.25;letter-spacing:-.04em;margin:0 0 24px;max-width:1000px}h3{margin:0 0 12px;font-size:24px}.lead{font-size:clamp(17px,2vw,23px);line-height:1.6;max-width:900px;color:#263b4a;margin:0 0 26px}.subtitle{font-size:20px;color:var(--muted);margin:-6px 0 34px}.muted{color:var(--muted);font-size:14px;line-height:1.65}.sources{border-top:1px solid var(--line);padding:15px 52px 18px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;font:700 11px ui-monospace,monospace;color:var(--muted)}.sources a{border:1px solid var(--line);border-radius:4px;padding:5px 7px;text-decoration:none}.sources a:hover{background:var(--pale)}.deck-controls{max-width:1260px;margin:0 auto;display:flex;align-items:center;gap:14px;padding:0 16px 26px}.navbtn{border:1px solid #c8d5da;background:#fff;border-radius:6px;padding:10px 16px;font-weight:800;color:var(--ink)}.navbtn:disabled{opacity:.3;cursor:not-allowed}.slide-count{font:700 13px ui-monospace,monospace;color:#506271;min-width:72px;text-align:center}.progress{flex:1;height:6px;border-radius:99px;overflow:hidden;background:#d2dfe6}.progress>div{height:100%;background:var(--accent);transition:width .2s}.shortcut{font-size:12px;color:#6b7d8c}.note{margin-top:25px;border-left:4px solid var(--accent);padding:13px 18px;background:var(--pale)}.note-label{font:800 11px ui-monospace,monospace;color:var(--accent);letter-spacing:.1em}.note p{margin:5px 0 0;line-height:1.6}.cover-visual{background:#152a37;color:#fff;border-radius:8px;padding:36px;min-height:245px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:25px;max-width:880px}.binary-chip{font:800 clamp(56px,10vw,125px) ui-monospace,monospace;letter-spacing:.02em}.binary-chip span{color:#f9d57e}.cover-path{font:600 12px ui-monospace,monospace;letter-spacing:.12em;color:#d1e3e8;text-align:center}.cover-path b{color:#f9d57e;margin:0 8px}.objectives{display:grid;grid-template-columns:1fr 1fr;gap:16px;max-width:960px}.objective{border:1px solid var(--line);border-radius:8px;display:flex;align-items:center;gap:20px;padding:23px}.objective b{font:800 24px ui-monospace,monospace;color:var(--accent)}.objective span{font-size:19px;font-weight:650}.two-col{display:grid;grid-template-columns:1.05fr .95fr;gap:26px;align-items:start}.truth-table{border-collapse:collapse;width:100%;font:750 20px ui-monospace,monospace;text-align:center}.truth-table td,.truth-table th{border-bottom:1px solid var(--line);padding:12px}.truth-table th{font-size:15px;color:var(--accent);background:#eef5f4}.live-panel{border:1px solid var(--line);background:#f9fcfc;border-radius:8px;padding:22px}.panel-heading{font-size:13px;font-weight:800;color:var(--muted);margin:0 0 18px}.bit-row{display:flex;gap:12px}.bit{border:2px solid #a7c7c3;background:#fff;color:var(--ink);padding:13px;border-radius:6px;flex:1;font:700 18px ui-monospace,monospace}.bit:hover{background:var(--pale)}.result-grid{display:flex;gap:12px;margin-top:18px}.result-grid>div{flex:1;background:#e5f1ef;padding:12px;text-align:center;color:#54716e;font:700 12px ui-monospace,monospace}.result-grid b{display:block;font-size:34px;color:var(--ink);padding:5px}.compare-pairs{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:950px}.pair{border:1px solid var(--line);border-top:5px solid var(--accent);border-radius:8px;padding:28px;background:#fafcfd}.pair>span,.mini-label{font:800 12px ui-monospace,monospace;color:var(--accent);letter-spacing:.08em}.pair p{font-size:17px;line-height:1.65;margin:12px 0}.pair .expression{font:800 34px ui-monospace,monospace;margin:19px 0 4px}.pair .answer{font:900 52px ui-monospace,monospace;color:var(--accent)}.pair .example{font-size:15px;color:var(--muted)}.formula-block{border:1px solid var(--line);padding:30px;border-radius:8px;display:flex;align-items:center;gap:24px;max-width:980px;flex-wrap:wrap;background:#fafdfe}.formula-block b{font:750 29px ui-monospace,monospace}.formula-block span{color:var(--accent);font-weight:800}.formula-block i{color:var(--muted)}.formula-block.alt{margin-top:16px;background:var(--pale)}.math-card{border:1px solid var(--line);padding:28px;border-radius:8px}.mathline{font:700 25px ui-monospace,monospace;margin:20px 0}.dff-demo{max-width:960px;padding:24px 28px;background:#f4f8fa;border:1px solid var(--line);border-radius:8px}.block-dff{display:flex;align-items:center;justify-content:center;gap:38px}.block-dff>span{font:900 30px ui-monospace,monospace}.block-dff strong{border:3px solid var(--ink);padding:22px;background:#fff;letter-spacing:.1em}.clockline{display:flex;gap:24px;align-items:center;justify-content:center;margin-top:20px}.clockline svg{width:70%;height:80px;color:var(--accent)}.clockline span{font:800 18px ui-monospace,monospace}.dff-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;max-width:960px;margin-top:20px}.dff-steps>div{padding:16px;border-left:3px solid var(--accent);background:#f6fafb}.dff-steps p{color:var(--muted);margin:8px 0 0;line-height:1.6}.fsm-stage{max-width:870px;border:1px solid var(--line);padding:25px;border-radius:9px;background:#f6fafb}.fsm-nodes{display:flex;align-items:center;justify-content:space-around;gap:10px}.fsm-node{background:#fff;border:3px solid #cbd4dc;border-radius:999px;width:152px;height:152px;display:flex;align-items:center;justify-content:center;flex-direction:column;font:900 27px ui-monospace,monospace;color:#8a98a7}.fsm-node.active{border-color:var(--accent);color:var(--accent);background:var(--pale)}.fsm-node small{font:500 13px system-ui;margin-top:5px}.fsm-arrows{color:var(--muted);font-weight:700}.fsm-controls{margin-top:20px;display:flex;align-items:center;justify-content:center;gap:25px}.action-button{border:0;background:var(--accent);color:#fff;padding:13px 19px;border-radius:6px;font-weight:800}.action-button:hover{background:#095956}.chain{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.chain a{border:1px solid var(--line);padding:15px;background:#f7fbfb;text-decoration:none;border-top:4px solid var(--accent);display:flex;min-height:160px;flex-direction:column;gap:12px}.chain small{font:700 12px ui-monospace,monospace;color:var(--accent)}.chain b{font-size:17px;color:var(--ink)}.chain span{margin-top:auto;font-size:12px}.quiz-list{display:grid;gap:12px}.quiz-q{border:1px solid var(--line);padding:13px 18px;border-radius:7px;min-width:0}.quiz-q legend{font-size:17px;font-weight:800;padding:0 7px}.choices{display:flex;flex-wrap:wrap;gap:16px}.quiz-choice{cursor:pointer;display:flex;align-items:center;gap:8px}.quiz-choice input{accent-color:var(--accent);width:18px;height:18px}.quiz-feedback{color:var(--accent);font-size:13px;margin:8px 0 0;min-height:18px}.quiz-actions{margin-top:14px;display:flex;align-items:center;gap:18px;font-weight:800}.end-summary{display:flex;align-items:center;gap:22px;background:var(--pale);padding:20px;margin-bottom:18px}.end-summary b{font:900 30px ui-monospace,monospace;color:var(--accent)}.end-summary span{font-size:20px;font-weight:700}.end-sources{display:grid;gap:7px;font-size:14px}.end-sources a{text-decoration:none}.final-actions{display:flex;gap:12px;margin-top:20px}.final-actions a{border:1px solid var(--accent);padding:11px 17px;border-radius:5px;text-decoration:none;font-weight:800}@media(max-width:750px){.topbar{height:auto;min-height:60px;padding:15px;flex-wrap:wrap}.topbar nav{gap:10px}.deck-shell{margin:12px auto 5px;padding:0 8px}.slide{min-height:660px}.slide-top{padding:20px 22px 0}.slide-content{padding:28px 26px}.sources{padding:14px 22px}.two-col,.compare-pairs,.objectives{grid-template-columns:1fr}.chain{grid-template-columns:repeat(2,1fr)}.dff-steps{grid-template-columns:1fr}.fsm-node{width:105px;height:105px;font-size:20px}.fsm-arrows{font-size:12px}.formula-block b{font-size:22px}.truth-table{font-size:17px}.result-grid b{font-size:26px}.cover-visual{min-height:175px;padding:20px}.shortcut{display:none}.objective{padding:12px}.objective span{font-size:16px}.mathline{font-size:20px}.end-summary span{font-size:16px}.quiz-q legend{font-size:15px}}@media print{body{background:white}.topbar,.deck-controls{display:none}.slide,.slide[hidden]{display:flex;min-height:670px;break-after:page;box-shadow:none;border:1px solid #ddd;margin-bottom:0}.deck-shell{max-width:none;margin:0;padding:0}}'''

slide_js=r'''(()=>{'use strict';const pages=[...document.querySelectorAll('.slide')], total=pages.length; let current=0;const prev=document.getElementById('prev'),next=document.getElementById('next'),meter=document.getElementById('meter'),counter=document.getElementById('counter');function show(n){current=Math.max(0,Math.min(n,total-1));pages.forEach((p,i)=>p.hidden=i!==current);prev.disabled=current===0;next.disabled=current===total-1;meter.style.width=((current+1)/total*100)+'%';counter.textContent=String(current+1).padStart(2,'0')+' / '+String(total).padStart(2,'0');history.replaceState(null,'','#'+pages[current].id);window.scrollTo({top:0,behavior:'instant'});}prev.addEventListener('click',()=>show(current-1));next.addEventListener('click',()=>show(current+1));document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}});let start=pages.findIndex(p=>'#'+p.id===decodeURIComponent(location.hash));show(start<0?0:start);
function setupBits(prefix,callback){let a=0,b=0;const ba=document.getElementById(prefix+'A'),bb=document.getElementById(prefix+'B');function render(){ba.querySelector('strong').textContent=a;bb.querySelector('strong').textContent=b;callback(a,b)}ba.onclick=()=>{a=1-a;render()};bb.onclick=()=>{b=1-b;render()};render()}
setupBits('logic',(a,b)=>{document.getElementById('logicAnd').textContent=a&b;document.getElementById('logicOr').textContent=a|b;document.getElementById('logicXor').textContent=a^b});setupBits('add',(a,b)=>{document.getElementById('addSum').textContent=a^b;document.getElementById('addCarry').textContent=a&b;document.getElementById('addExplanation').textContent=`${a} + ${b} = ${String(a&b)}${String(a^b)}（2 進位）`});let fsm=0;document.getElementById('fsmToggle').onclick=()=>{fsm=1-fsm;document.getElementById('offNode').classList.toggle('active',fsm===0);document.getElementById('onNode').classList.toggle('active',fsm===1);document.getElementById('fsmStateText').textContent='目前狀態：'+(fsm?'ON':'OFF')};document.getElementById('quizCheck').onclick=()=>{let score=0;let answered=0;document.querySelectorAll('.quiz-q').forEach(q=>{const chosen=q.querySelector('input:checked'),feedback=q.querySelector('.quiz-feedback');if(!chosen){feedback.textContent='尚未作答';return}answered++;if(Number(chosen.value)===Number(q.dataset.correct)){score++;feedback.textContent='✓ 正確。'+q.dataset.why}else{feedback.textContent='✗ 再想想。'+q.dataset.why}});document.getElementById('quizTotal').textContent=`答對 ${score}/3 題（已作答 ${answered}/3 題）`};})();'''

