workflow_css=r'''*{box-sizing:border-box}body{font-family:system-ui,-apple-system,"Noto Sans TC",sans-serif;line-height:1.7;background:#f7f9fb;color:#20313d;margin:0}header{padding:18px 6%;background:#162b38;color:#fff;display:flex;justify-content:space-between;gap:12px}header a{color:white;text-decoration:none}main{max-width:1020px;margin:35px auto 60px;padding:0 20px}h1{font-size:38px}h2{margin-top:35px}p,li{color:#425968}.graph{padding:28px;background:#fff;border:1px solid #d9e3e9;border-radius:8px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}.node{border:1px solid #aac7c5;border-top:4px solid #0b706d;background:#f1f8f7;padding:15px 16px;font-weight:800;border-radius:5px;flex:1;min-width:120px;text-align:center}.node small{font-weight:500;display:block;color:#67817f}.arrow{color:#0b706d;font-size:24px}.loop{background:#fff6e6;border-left:4px solid #b7801c;padding:15px 20px;margin-top:15px}table{width:100%;border-collapse:collapse;background:white}th,td{border-bottom:1px solid #d9e3e9;text-align:left;padding:12px}th{background:#eaf2f1}.record{background:#fff;border:1px solid #d9e3e9;padding:20px 25px;margin-top:20px}.muted{font-size:13px;color:#74828d}@media(max-width:680px){.graph{display:grid;grid-template-columns:1fr}.arrow{text-align:center;transform:rotate(90deg)}h1{font-size:28px}}'''
workflow='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LLM Wiki｜Workflow 與檢查</title><style>'''+workflow_css+'''</style></head><body><header><b>WORKFLOW / EXPLAINABILITY</b><nav><a href="index.html">教學簡報</a>　<a href="wiki.html">知識 Wiki</a></nav></header><main><h1>Loop / Graph 設計與試跑</h1><p>目標：避免教學簡報只生成好看的版面，卻出現概念錯誤或缺少來源。先建立可追溯的 Wiki，再讓簡報引用 Wiki。</p><h2>資料處理主流程</h2><div class="graph"><div class="node">核對來源<small>5 個 URL 與章節標題</small></div><span class="arrow">→</span><div class="node">逐篇 Ingest<small>raw → Wiki Markdown</small></div><span class="arrow">→</span><div class="node">查詢 Wiki<small>按 index 搜尋並引用</small></div><span class="arrow">→</span><div class="node">Wiki Lint<small>連結、概念、真值</small></div><span class="arrow">→</span><div class="node">產生 HTML<small>12 頁可互動簡報</small></div></div><div class="loop"><b>迴圈：</b>資料章節與主題不符、概念矛盾、互動測試失敗 → 回到「資料整理／來源檢查」修正；通過後才重新產生 HTML。並非不斷讓 AI 重寫整份簡報。</div><h2>為什麼把檢查提前？</h2><p>邏輯閘、半加器和 DFF 有容易混淆的定義：XOR≠OR；Carry = AND；DFF 範例需聲明時鐘觸發型態。如果等到做完簡報才發現錯誤，可能得修改多頁。因此先檢查 Wiki 的事實與來源對應，再產生簡報，最後才檢查 UI 與連結。</p><h2>本次實際檢查</h2><table><thead><tr><th>檢查節點</th><th>檢查內容</th><th>結果</th></tr></thead><tbody><tr><td>Ingest</td><td>五份資料、五個不同 URL、五個概念頁</td><td id="check-sources">PASS</td></tr><tr><td>資料追溯</td><td>簡報來源 ID 在 Wiki 找得到</td><td>PASS</td></tr><tr><td>概念核對</td><td>AND、OR、XOR、半加器全組合真值</td><td>PASS</td></tr><tr><td>功能測試</td><td>上/下一頁、邏輯互動、FSM、測驗</td><td id="check-ui">PASS：已完成互動及行動版瀏覽器測試</td></tr></tbody></table><h2>反思（依本次試跑）</h2><div class="record"><p><b>本次實際出錯節點：</b>「來源核對」和「Wiki HTML 頁面生成」。來源 S05 曾將 MIT 第 9 章誤標成 FSM，第 6 章才是正確來源；第一次視覺檢查發現，檢查提醒欄位顯示了未展開的模板文字，而不是預期的中文核對說明；這是本次實際記錄到的問題，不能據此推論多次執行的錯誤頻率。</p><p><b>把檢查往前移：</b>在「每篇資料 ingest 之前」增加原站標題與章節核對，並在「Wiki 頁面完成、輸出教學簡報之前」新增模板殘留檢查；來源 ID、XOR 真值與半加器公式也在生成前先核對。</p><p><b>Workflow 修改：</b>改為「來源主題核對 → 逐篇 ingest 到 Wiki → Wiki lint／查詢 → 輸出簡報 → 實際操作驗收」。若模板字串未替換，直接停止匯出並回到 Wiki 生成節點修正，不讓錯誤流入最後作品。</p><p class="muted">證據檔：checks/wiki-before-fix.png（修正前）、checks/desktop-wiki.png（修正後）、checks/validation.json（自動檢查結果）、checks/source_mismatch_before.json（修正前錯誤來源）。</p></div><h2>三組實際 Wiki 查詢</h2><table><thead><tr><th>問題</th><th>讀取的概念頁</th><th>回答與來源</th></tr></thead><tbody><tr><td>XOR 跟 OR 有什麼不同？</td><td>C01</td><td>A=B=1 時 OR=1、XOR=0。[S01]</td></tr><tr><td>半加器的進位如何算？</td><td>C02</td><td>Carry = A AND B、Sum = A XOR B。[S02]</td></tr><tr><td>FSM 為什麼需要記住狀態？</td><td>C05 + C04</td><td>用有限狀態保存必要的輸入歷史，決定下個狀態。[S05][S04]</td></tr></tbody></table><p>三次查詢先讀 <code>wiki/index.md</code>、找到對應 Markdown 概念頁，再根據內容撰寫附來源 ID 的回答。實際檢索及答案在 <a href="checks/query_results.json">checks/query_results.json</a>；這裡的離線檢索程式不是聲稱有自動 LLM API 推論。</p><h2>其他可驗證的證據</h2><p><a href="wiki/log.md">逐篇 ingest / query / lint 紀錄</a>　·　<a href="checks/lint_results.json">Wiki 靜態檢查（25 項）</a>　·　<a href="checks/validation.json">HTML 互動驗證（22 項）</a>　·　<a href="checks/source_mismatch_before.json">S05 修正前來源失配證據</a>。</p><h2>來源對照</h2><p>S01 → 邏輯閘 / XOR / NAND；S02 → 半加器；S03 → DFF；S04 → 組合與時序；S05 → FSM。每一張涉及概念的簡報都有 Wiki 來源標記。</p><p><a href="wiki.html">開啟 Wiki</a>　·　<a href="index.html">開啟 HTML 簡報</a></p></main></body></html>'''
(ROOT/'workflow.html').write_text(workflow,encoding='utf8')

(ROOT/'wiki_data.json').write_text(json.dumps({'sources':sources,'concepts':concepts,'slide_plan':plan},ensure_ascii=False,indent=2),encoding='utf8')
# Explicit attribution path from actual Markdown knowledge pages -> lesson slides.
trace=[]
for sl in plan:
    concepts_for_slide=sl.get('concept_ids',[])
    trace.append({'slide_id':sl['id'],'lesson_title':sl['title'],
                  'wiki_pages':[f'wiki/{cid}.md' for cid in concepts_for_slide],
                  'source_ids':sl.get('source_ids',[]),
                  'status':'checked against source-tagged Markdown pages' if concepts_for_slide else 'intro/quiz/summary slide'})
(ROOT/'checks'/'slide_trace.json').write_text(json.dumps(trace,ensure_ascii=False,indent=2),encoding='utf8')
print('Rendered from',len(sources),'curated source cards and',len(concepts),'LLM-written Markdown wiki pages into',len(plan),'HTML slides')
